#!/usr/bin/env bash
# Shared config loader for the container build/run/cleanup scripts.
#
# Sources containerconf/.env (generated by ./setup.sh) and applies defaults,
# so no script hardcodes host paths, a runtime, or a port list. Also sources
# versions.env (the committed toolchain pins).
#
# Usage (top of every script):
#   SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
#   source "$SCRIPT_DIR/config.sh"

set -euo pipefail

CONF_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

# The .env is machine-specific (paths, ports, names) and must never be committed.
if [ -f "$CONF_DIR/.env" ]; then
  set -a
  # shellcheck disable=SC1091
  source "$CONF_DIR/.env"
  set +a
else
  echo "No containerconf/.env found." >&2
  echo "Run containerconf/setup.sh once to generate it for this machine." >&2
  exit 1
fi

# --- defaults (accept the generated values or fall back if unset) ----------
: "${XPAL_RUNTIME:=}"
: "${XPAL_IMAGE:=xpal-claudia}"
: "${XPAL_CONTAINER:=xpal-dev}"
: "${XPAL_CONTAINER_REMOTE:=xpal-dev-remote}"
: "${XPAL_HOST_SRC:=$HOME/xpal-src}"
: "${XPAL_HOST_DATA:=$HOME/xpal-data}"
: "${XPAL_HOST_AUTH:=$HOME/xpal-auth}"
: "${XPAL_PORTS:=5001:5001 8001:8001 8080:8080}"
: "${XPAL_HOST_REMOTE_DIR:=}"
: "${XPAL_AS_CODER:=0}"

# Toolchain pins + the coder fallback's UID. Committed, not machine-specific.
# shellcheck disable=SC1091
source "$CONF_DIR/versions.env"

# Pick a runtime if setup didn't pin one: prefer podman, fall back to docker.
if [ -z "$XPAL_RUNTIME" ]; then
  if command -v podman >/dev/null 2>&1; then
    XPAL_RUNTIME=podman
  elif command -v docker >/dev/null 2>&1; then
    XPAL_RUNTIME=docker
  else
    echo "No container runtime found (need podman or docker on PATH)." >&2
    exit 1
  fi
fi

# Expand the space-separated port list into `-p host:container` args.
PORT_ARGS=()
for p in $XPAL_PORTS; do
  PORT_ARGS+=( -p "$p" )
done

# Who the container runs as. Default: root, which under rootless Podman maps to
# your host user — no flags needed, mounts are writable, files stay yours (see
# ADR-008). XPAL_AS_CODER=1 runs as the fallback `coder` user instead (for tools
# that refuse root): keep-id:uid=,gid= maps your host user onto coder's fixed
# UID so the mounts stay writable. Podman only; applies when the container is
# CREATED, so recreate it to switch.
USER_ARGS=()
if [ "$XPAL_AS_CODER" = "1" ]; then
  USER_ARGS=( --user coder "--userns=keep-id:uid=$CODER_UID,gid=$CODER_UID" )
fi
